def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def f(g):
    g=np.array(g); H,W=g.shape
    cnt=Counter(g.flatten().tolist()); bg=cnt.most_common(1)[0][0]
    lines=[]
    for ii in range(H):
        s=set(g[ii])
        if len(s)==1 and next(iter(s))!=bg: lines.append(('h',ii,int(next(iter(s)))) )
    for jj in range(W):
        s=set(g[:,jj])
        if len(s)==1 and next(iter(s))!=bg: lines.append(('v',jj,int(next(iter(s)))) )
    L=lines[0]; axis=L[0]; lpos=L[1]; lc=L[2]
    vis=np.zeros_like(g,bool); comps=[]
    for i in range(H):
        for j in range(W):
            c=int(g[i,j])
            if c==bg or c==lc or vis[i,j]: continue
            st=[(i,j)]; comp=[]
            while st:
                a,b=st.pop(); comp.append((a,b,int(g[a,b])))
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                    x,y=a+da,b+db
                    if 0<=x<H and 0<=y<W and int(g[x,y])!=bg and int(g[x,y])!=lc and not vis[x,y]:
                        vis[x,y]=True; st.append((x,y))
            comps.append(comp)
    def bbox_full(c):
        rs=[i for i,j,v in c]; cs=[j for i,j,v in c]
        return len(set(zip(rs,cs)))==(max(rs)-min(rs)+1)*(max(cs)-min(cs)+1)
    objs=[c for c in comps if not bbox_full(c)]
    obj=max(objs,key=len) if objs else max(comps,key=len)
    lo=min(i for i,j,v in obj); hi=max(i for i,j,v in obj)
    li=min(j for i,j,v in obj); ri=max(j for i,j,v in obj)
    out=g.copy()
    for i,j,_ in obj: out[i,j]=bg
    # determine direction toward line
    if axis=='h':
        if hi>lpos:   # below: slide UP, near=top, far=bottom
            off=(lpos+1)-lo; dr=-1; far=max_edge=hi
        else:         # above: slide DOWN, near=bottom, far=top
            off=(lpos-1)-hi; dr=+1; far=max_edge=lo
    else:
        if ri>lpos:   # right: slide LEFT, near=right, far=left
            off=(lpos+1)-ri; dr=-1; far=min_edge=li
        else:          # left: slide RIGHT, near=left, far=right
            off=(lpos-1)-li; dr=+1; far=min_edge=ri
    far = (max(i for i,j,_ in obj) if dr==dr*0 else min(i for i,j,_ in obj)) if axis=='h' else None
    # simpler: use bbox bounds and direction: after move, edge away from line moves further
    if axis=='h':
        if hi>lpos: new_hi=hi+off; r8=new_hi+1
        else: new_lo=lo+off; r8=new_lo-1
    else:
        if ri>lpos: new_li=li+off; c8=new_li-1
        else: new_ri=ri+off; c8=new_ri+1
    for i,j,v in obj: out[i+off][j if axis=='h' else j]=v
    if axis=='h':
        for j in range(W): out[r8][j]=8
    else:
        for i in range(H): out[i][c8]=8
    return [[int(v) for v in r] for r in out]

